{
    "name": "049_group_limited_topk_routing",
    "hf_id": "inclusionAI/Ring-flash-2.0",
    "description": "Group-limited top-k expert routing for Mixture of Experts. Implements a two-stage selection: first organizes 256 experts into 8 groups, computes group scores by summing top-2 expert scores within each group, selects top-4 groups, then picks top-8 experts from selected groups. Returns selected expert indices and normalized routing weights scaled by routed_scaling_factor.",
    "axes": {
        "num_tokens": {
            "type": "var",
            "description": "Number of tokens (batch_size * seq_len)"
        },
        "num_experts": {
            "type": "const",
            "value": 256,
            "description": "Total number of experts"
        },
        "num_experts_per_tok": {
            "type": "const",
            "value": 8,
            "description": "Number of experts selected per token (top_k)"
        },
        "n_group": {
            "type": "const",
            "value": 8,
            "description": "Number of expert groups"
        },
        "topk_group": {
            "type": "const",
            "value": 4,
            "description": "Number of groups to select"
        },
        "gating_dim": {
            "type": "const",
            "value": 4096,
            "description": "Hidden dimension for gating"
        },
        "experts_per_group": {
            "type": "expr",
            "expression": "num_experts // n_group",
            "description": "Number of experts per group (32)"
        }
    },
    "custom_inputs_entrypoint": null,
    "inputs": {
        "hidden_states": {
            "shape": [
                "num_tokens",
                "gating_dim"
            ],
            "dtype": "bfloat16",
            "description": "Input token representations"
        },
        "weight": {
            "shape": [
                "num_experts",
                "gating_dim"
            ],
            "dtype": "bfloat16",
            "description": "Routing weight matrix"
        },
        "expert_bias": {
            "shape": [
                "num_experts"
            ],
            "dtype": "bfloat16",
            "description": "Expert bias for routing adjustment"
        },
        "routed_scaling_factor": {
            "shape": null,
            "dtype": "float32",
            "description": "Scaling factor for routing weights"
        }
    },
    "outputs": {
        "topk_idx": {
            "shape": [
                "num_tokens",
                "num_experts_per_tok"
            ],
            "dtype": "int64",
            "description": "Selected expert indices"
        },
        "topk_weight": {
            "shape": [
                "num_tokens",
                "num_experts_per_tok"
            ],
            "dtype": "float32",
            "description": "Normalized and scaled routing weights"
        }
    },
    "reference": "import torch\nimport torch.nn.functional as F\n\n@torch.no_grad()\ndef run(\n    hidden_states: torch.Tensor,\n    weight: torch.Tensor,\n    expert_bias: torch.Tensor,\n    routed_scaling_factor: float,\n):\n    \"\"\"\n    Group-limited top-k expert routing.\n    \n    Two-stage selection:\n    1. Organize 256 experts into 8 groups of 32\n    2. Compute group scores by summing top-2 expert scores within each group\n    3. Select top-4 groups based on group scores\n    4. Mask out experts from non-selected groups\n    5. Select top-8 experts from remaining candidates\n    6. Normalize weights and apply scaling factor\n    \"\"\"\n    # Constants\n    num_experts = 256\n    top_k = 8\n    n_group = 8\n    topk_group = 4\n    experts_per_group = num_experts // n_group  # 32\n    \n    num_tokens = hidden_states.shape[0]\n    \n    # Compute routing logits: [num_tokens, 256]\n    logits = F.linear(\n        hidden_states.to(torch.float32),\n        weight.to(torch.float32)\n    )\n    \n    # Apply sigmoid activation to get routing scores\n    scores = torch.sigmoid(logits)  # [num_tokens, 256]\n    \n    # Add learned expert bias for routing adjustment\n    scores_for_routing = scores + expert_bias.to(torch.float32)\n    \n    # Step 1: Reshape scores into groups [num_tokens, 8, 32]\n    group_scores_reshaped = scores_for_routing.view(num_tokens, n_group, experts_per_group)\n    \n    # Step 2: Get top-2 scores within each group and sum them\n    # [num_tokens, 8, 2] -> [num_tokens, 8]\n    top2_vals, _ = torch.topk(group_scores_reshaped, k=2, dim=-1, largest=True, sorted=False)\n    group_scores = top2_vals.sum(dim=-1)  # [num_tokens, 8]\n    \n    # Step 3: Select top-4 groups based on aggregated scores\n    # [num_tokens, 4]\n    _, group_idx = torch.topk(group_scores, k=topk_group, dim=-1, sorted=False)\n    \n    # Step 4: Create group mask [num_tokens, 8]\n    group_mask = torch.zeros_like(group_scores)\n    group_mask.scatter_(1, group_idx, 1.0)\n    \n    # Step 5: Expand mask to expert level [num_tokens, 256]\n    score_mask = (\n        group_mask.unsqueeze(-1)\n        .expand(num_tokens, n_group, experts_per_group)\n        .reshape(num_tokens, num_experts)\n    )\n    \n    # Step 6: Mask out experts from non-selected groups\n    neg_inf = torch.finfo(torch.float32).min\n    masked_scores = scores_for_routing.masked_fill(score_mask == 0, neg_inf)\n    \n    # Step 7: Select top-8 experts from masked scores\n    _, topk_idx = torch.topk(masked_scores, k=top_k, dim=-1, sorted=False)\n    \n    # Gather selected expert scores (use original scores without bias)\n    selected_scores = torch.gather(scores, dim=1, index=topk_idx)\n    \n    # Normalize routing weights\n    topk_weight = selected_scores / (selected_scores.sum(dim=-1, keepdim=True) + 1e-20)\n    \n    # Apply routing scaling factor\n    topk_weight = topk_weight * routed_scaling_factor\n    \n    return topk_idx, topk_weight\n"
}

